[
  {
    "pd_harm_distress": "My hands are shaking just thinking about it",
    "sys_consequence_reasoning": "Five lives saved against none lost on the siding side",
    "sys_rule_justification": "protecting life when you're able to is simply something you owe as a bystander",
    "pda_repair_intention": "go straight to the workers and to the rail authority, explain exactly what happened"
  },
  {
    "pd_harm_distress": "I feel sick even imagining my hand on that lever",
    "sys_consequence_reasoning": "Letting five people die when one safe action stops it seems like the greater wrong",
    "sys_rule_justification": "if you can prevent serious harm without harming anyone else, you're obligated to try",
    "pda_repair_intention": "sit down with my supervisor and file a full account"
  },
  {
    "pd_harm_distress": "My chest is tight just picturing the train moving toward them",
    "sys_consequence_reasoning": "five saved lives outweighs the empty risk of the siding",
    "sys_rule_justification": "There's a principle I trust here, that avoidable death matters more than inaction's comfort",
    "pda_repair_intention": "speak with the crew directly, apologize for the fright, and help write up the incident"
  },
  {
    "pd_harm_distress": "Honestly my stomach turns over just thinking about the decision",
    "sys_consequence_reasoning": "doing nothing while five people could die feels like a choice too, and a worse",
    "sys_rule_justification": "I follow the rule that we must act to prevent serious harm",
    "pda_repair_intention": "explain myself to the site manager and make sure the workers know why"
  },
  {
    "pd_harm_distress": "even if my hands would be trembling",
    "sys_consequence_reasoning": "Five workers saved against zero cost elsewhere isn't a hard call",
    "sys_rule_justification": "there's a duty to intervene when intervention is safe and effective",
    "pda_repair_intention": "insist on meeting with the crew to explain what I saw and why I acted",
    "ce_contextual_explanation": "so they don't carry unnecessary confusion or fear"
  },
  {
    "pd_harm_distress": "It unsettles me deeply to even imagine that lever under my hand",
    "sys_consequence_reasoning": "Saving five lives against none endangered on the other track just outweighs standing still",
    "sys_rule_justification": "when a duty to prevent harm is clear and safe to fulfill, you follow it",
    "pda_repair_intention": "speak to the supervisor and the workers, walk them through exactly what triggered the switch"
  },
  {
    "pd_harm_distress": "I'm not fully certain I could stay steady",
    "sys_consequence_reasoning": "five spared against nobody harmed by the diversion",
    "sys_rule_justification": "preventable death demands action from anyone able to give it",
    "pda_repair_intention": "write a full report and personally apologize to the men for the scare"
  },
  {
    "pd_harm_distress": "My pulse is racing just thinking through this",
    "sys_consequence_reasoning": "letting five people be struck when a safe alternative exists seems like a terrible outcome",
    "sys_rule_justification": "bound to prevent avoidable harm when we're capable and safe doing so",
    "pda_repair_intention": "talk with the workers myself, explain the split-second choice, and offer to help"
  },
  {
    "pd_harm_distress": "This scenario makes my hands go cold",
    "sys_consequence_reasoning": "Five people spared against an empty siding barely counts as a real cost",
    "sys_rule_justification": "inaction causing death is not morally neutral when prevention is available",
    "pda_repair_intention": "meet with the maintenance crew, explain my reasoning, and offer to assist"
  },
  {
    "pd_harm_distress": "I feel shaky just imagining the sound of that train",
    "sys_consequence_reasoning": "five lives saved against a controlled stop elsewhere isn't a close call for me",
    "sys_rule_justification": "when you can prevent serious harm at no cost to anyone, you're required to try",
    "pda_repair_intention": "sit with the crew, explain what happened, and make sure the report reflects the truth"
  }
]
